from engine import *
topics=[
I('project','Същият сайт, този път в онлайн редактор',P('Задачата от учебника отново е сайт <strong>„София“</strong> с Начало, История, География и Храмове. Разликата е инструментът: използва се <strong>Wix</strong> през браузър, а не настолният Composer.','Онлайн редакторът предлага работно поле, страници и готови оформления. Ние подреждаме съдържанието, а платформата управлява много от техническите части. Това не премахва нуждата да мислим за текста, снимките и връзките.','В този урок проследяваме завършен учебен пример. Не е необходимо да създаваш профил или да публикуваш личен сайт. Показаните схеми обясняват действията, а действителният интерфейс може да се различава според версията на редактора.')+E('Целта остава същата: посетителят да намира четири свързани теми с последователен вид. Красивият шаблон е начало, а не готово съдържание за София.'),[('Проект','София: Начало, История, География, Храмове'),('Инструмент','Wix — онлайн редактор'),('Проверка','Последователен вид и работещи връзки')],C('Кои твърдения отговарят на примера?',['Темата е София.','Нужни са начална и три вътрешни страници.','Онлайн редакторът работи през браузър.','Готовият шаблон автоматично знае всички наши текстове и снимки.','Съдържанието и навигацията пак трябва да се планират.','Отварянето на редактора непременно означава публикуван личен сайт.'],[0,1,2,4],'Платформата е инструмент; целта, структурата и съдържанието остават наша задача. Шаблонът и отвореният редактор не са готова публикация.')),
I('account','Регистрация и вход: различни действия',P('Учебникът започва с отваряне на <strong>wix.com</strong>. <strong>Get Started</strong> насочва към начало на работа, <strong>Sign Up</strong> — към създаване на профил, а <strong>Log In</strong> — към вход в съществуващ профил.','Профилът е нужен, за да се съхранява проектът в платформата и да се управлява от своя автор. В готовата ситуация вече има подготвен учебен профил и се отваря неговият проект. Не е необходимо всеки читател на публичния сайт да има редакторски профил.','След вход платформата може да попита какъв сайт се създава, за име и допълнителни възможности. В примера от учебника част от въпросите могат да се пропуснат. Не бива само по въпросника да заключаваме, че проектът вече е завършен.')+E('Входът отваря достъп до проекта на автора. Посетителят по-късно отваря публикувания адрес, за да разгледа сайта. Това са различни роли.'),[('Sign Up','Създаване на профил'),('Log In','Вход в съществуващ профил'),('Посетител','Разглежда публикувания адрес')],C('Кои разграничения са правилни?',['Sign Up е регистрация.','Log In е вход.','Редакторският профил управлява проекта.','Всеки посетител задължително трябва да редактира сайта.','Посетител и автор имат различни роли.','Попълнен въпросник гарантира готово проверено съдържание.'],[0,1,2,4],'Регистрацията, входът и посещаването имат различни цели. Авторът подготвя проекта; посетителят вижда публикуваното съдържание.')),
I('template','Шаблонът е начална подредба',P('<strong>Шаблон</strong> е готова начална структура и оформление, което можем да променим. Учебникът показва избор на <strong>blank template</strong> — празен шаблон — и вариант <strong>Strip Header Layout</strong>. Важна е идеята за подредба с обща заглавна част, а не заучаването на един етикет.','В готовия пример е избран подходящ вариант и е натиснат <strong>Edit</strong>. Отваря се редакторът. В него вече може да има примерни текстове или празни места; те трябва да се заменят със съдържание за София.','Шаблонът не е същото като тема на урок. Той е техническо начало на страницата. Избираме го според нуждите на сайта: място за заглавие, меню, текст и изображения. Точните налични шаблони могат да се променят.')+E('Ако началният вариант е за ресторант, не оставяме меню за храна в сайта за историята на София. Общият вид се приспособява към нашата цел.'),[('Избор','Празен или подходящ начален шаблон'),('Edit','Отваря редактора'),('Промяна','Собствени заглавия, текстове и изображения')],C('Кои твърдения за шаблона са верни?',['Дава начална подредба.','Може да бъде променян.','Трябва да отговаря на нуждите на сайта.','Никога не изисква замяна на примерните надписи.','Edit отваря възможност за редакция в примера.','Името на един шаблон гарантира вечна наличност във всички версии.'],[0,1,2,4],'Шаблонът е начало, което се приспособява. Наличностите и интерфейсът могат да се изменят.')),
I('customize','Заменяме примерното съдържание',P('В редактора заглавието е сменено на <strong>София</strong>, а под него е поставено кратко представяне на града. Променени са фонът и цветовете така, че текстът да се чете ясно.','В описания в учебника класически редактор много елементи могат да се изберат и редактират чрез щракване или двукратно щракване. Но първо трябва да е избран правилният елемент — например заглавието, а не фонът зад него.','Персонализиране означава приспособяване към проекта. То не е само смяна на цвета: включва правилни текстове, изображения и подредба. Общият стил трябва да се запази и във вътрешните страници.')+E('Преди: „Your Title Here“ и произволна снимка. След: „София“, собствено кратко описание и изображение, което представя града. Посетителят вече разбира каква е темата.'),[('Преди','Примерен надпис и изображение'),('След','София + подходящ собствен текст'),('Стил','Четими цветове и обща подредба')],C('Кои промени са подходящи?',['Замяна на примерното заглавие.','Добавяне на собствено тематично описание.','Запазване на четим контраст.','Оставяне на несвързани примерни реклами във всяка страница.','Избор на правилния елемент преди редакция.','Персонализиране означава само случайно сменяне на един цвят.'],[0,1,2,4],'Приспособяването включва съдържание, вид и подредба. Точният избор на елемент предотвратява промени на грешно място.')),
I('images','Добавяме изображение и го проверяваме',F('cathedral','Снимка на храм „Свети Александър Невски“ за тематична страница.')+P('В стъпката за съдържание учебникът показва <strong>Add Elements → Image</strong>. За собствен графичен файл се използва <strong>Upload & Import → Upload Images</strong> или съответната команда за качване. Файлът може да се избере или да се постави в прозореца чрез влачене, когато това е поддържано.','В готовия пример е добавена подходяща снимка на храм към страницата Храмове. След качването тя трябва да бъде избрана и поставена в страницата — наличието ѝ в библиотеката не означава непременно, че вече се вижда в проекта.','Размерът е съобразен с полето, пропорциите са запазени и има смислено описание. Изображението трябва да се зарежда и в прегледа. За използваните материали се спазват нужните права и признания за авторство.')+E('Пример: снимката е в медийната библиотека, но не е в страницата. Решението е да се постави на избраното място и да се провери изгледът, а не да се качва безкрайно още веднъж.'),[('Качване','Файлът влиза в медийната библиотека'),('Поставяне','Избраното изображение е в страницата'),('Преглед','Размер, описание и зареждане')],C('Кои действия са разграничени правилно?',['Качването добавя файла към библиотеката.','Поставянето добавя избраното изображение в страницата.','Прегледът проверява видимия резултат.','Наличието в библиотеката винаги означава автоматично правилно място на всяка страница.','Пазим пропорциите и смисленото описание.','Правото за използване няма значение за чужди изображения.'],[0,1,2,4],'Качване, поставяне и проверка са отделни действия. Изображението трябва да е подходящо и да се използва при съответните условия.')),
I('pages','Дублираме страница и сменяме темата',P('Сайтът трябва да има четири страници. В примера е отворено менюто за страници и от контекстното меню на <strong>Home</strong> е избрано дублиране. Така новата страница наследява общата подредба.','Копието е преименувано на <strong>История</strong>. В него са сменени заглавието, основният текст и изображението. Следващите копия стават География и Храмове. Начало остава отделна страница с общо представяне.','Не е достатъчно да сменим само името в списъка. Ако текстът вътре продължава да е за друга тема, посетителят ще бъде объркан. Менюто трябва да показва точните страници и да води до тях.')+T(['Страница','Собствено съдържание'],[['Начало','Кратко представяне.'],['История','Историческа информация.'],['География','Място и околности.'],['Храмове','Тематични текстове и снимки.']]),[('Дублиране','Запазва общата подредба'),('Преименуване','История / География / Храмове'),('Подмяна','Собствен текст и изображение във всяко копие')],C('Кои действия са необходими?',['Дублиране на подходящата подредба.','Преименуване на новата страница.','Смяна на тематичния текст и изображение.','Оставяне на еднакъв случаен текст навсякъде.','Проверка на менюто.','Изтриване на началната страница, защото вече има копие.'],[0,1,2,4],'Копието пази вида, но съдържанието и навигацията трябва да отразяват новата тема. Начало има собствена роля.')),
I('publish','Преглед и публикуване са различни стъпки',P('Преди публикация се отваря <strong>Preview — Преглед</strong>. Проверяват се страниците и връзките, текстът, снимките и подредбата. Грешките се поправят в редактора, а след това прегледът се повтаря.','В показания процес <strong>Publish — Публикувай</strong> прави сайта достъпен на уеб адрес. Самото записване на промяна в редактора не означава непременно, че посетителите вече виждат новата версия. След промени може да е нужно ново публикуване.','В готовия пример авторът е публикувал, после е отворил действителния адрес в браузъра. Там е проверено дали е достъпна правилната версия. Не публикуваме реален личен проект в тази мисия; сравняваме резултатите от двете действия.')+E('Преди Publish виждаме проверена чернова. След успешна публикация посетител отваря уеб адреса. Това е разликата между изглед за работа и достъпна версия.'),[('Preview','Проверка на проекта'),('Publish','Достъпна уеб версия'),('След промяна','Проверка и при нужда повторна публикация')],C('Кои твърдения са верни?',['Preview помага за проверка.','Publish публикува достъпна версия.','Проверяваме и действителния адрес след публикацията.','Всяка записана чернова автоматично е видима на всички посетители.','След промени може да е нужна нова публикация.','Щом началната страница е красива, останалите връзки не се проверяват.'],[0,1,2,4],'Редакторът, прегледът и публикуваната версия имат различни роли. Проверяват се всички страници и актуалността на публикацията.')),
I('final-test','Последна проверка: широк и тесен изглед',P('Учебникът завършва с два важни съвета: сайтът да се разгледа и в мобилен изглед и да се изпробват функциите. За тази проверка не е задължително да притежаваш телефон — редакторският преглед и тесният прозорец могат да покажат част от проблемите.','В готовите наблюдения широкият изглед е четим. В тесния менюто първоначално закрива заглавието. След корекция менюто се събира, а текстът и снимките остават в рамките на екрана.','От Начало са отворени История, География и Храмове, а после е проверено връщането. Ако има форма за контакт, не е достатъчно да изглежда красиво: трябва да се провери очакваният резултат от изпращането в подходящата тестова среда. Проверка, която не е извършена, не се отбелязва като успешна.')+E('В готовия сайт четирите страници и изображенията се отварят. Тесният изглед е поправен. Формуляр не е включен в този проект, затова не твърдим, че е тестван.'),[('Широк изглед','Четим'),('Тесен изглед','Менюто е коригирано и се събира'),('Връзки','Проверени между четирите страници')],O('Какъв извод за готовността на сайта следва от показаните проверки?','Напиши 3–5 изречения със свои думи и използвай поправеното меню като конкретен пример.','Показаните проверки потвърждават, че четирите страници и изображенията се отварят. В тесния изглед менюто първоначално е закривало заглавието, но е поправено и проверено отново. Това е важна част от подготовката за публикация. Не твърдим, че е тествана форма за контакт, защото такава няма в проекта. За самопроверка: свържи извода с наблюденията, а не само с общо „сайтът е хубав“.'))]
build(20,'website-components-practice','Създаване и интегриране на компонентите на сайт — упражнение','57',P('Ще проследиш създаването на четиристраничен сайт „София“ с Wix: от началния профил и шаблон до собствено съдържание, страници и проверена публикация.','Готовите примери показват какво се променя след всяко действие. Не е необходимо да се регистрираш, да качваш лични снимки или да публикуваш сайт. Целта е да разбираш процеса, а не да помниш наизуст всички английски надписи.'),topics,['<strong>Онлайн редакторът е инструмент, а планът и съдържанието са наши решения.</strong>','<strong>Шаблонът се приспособява чрез собствени текстове, изображения и стил.</strong>','<strong>Дублираните страници пазят общия вид, но получават собствена тема.</strong>','<strong>Преглед, запис и публикация са различни действия.</strong>','<strong>Проверяваме връзки, изображения, тесен изглед и наличните функции.</strong>'],['Стр.57: Wix/getstarted/login/signup/въпросник; blanktemplate/StripHeaderLayout/Edit; персонализиране; AddElements/Image/UploadImport/влачене; редакция; Home/дублиране/преименуване/темисъдържание; Publish; мобиленизглед/връзки/форми.'],[('Wix: публикуване','https://support.wix.com/en/article/wix-editor-publishing-your-site'),('Wix: помощ','https://support.wix.com/en/'),('Wikimedia: снимка на храма','https://commons.wikimedia.org/wiki/File:St._Alexander_Nevsky_Cathedral,_Sofia.jpg')], 'Това е обяснен пример по класическия процес от учебника; интерфейсът може да се променя. Не са създадени профил или публичен ученически сайт. Публикуването е разграничено от запазване; мобилният изглед може да се анализира без телефон.')
